# -*- coding: utf-8 -*-
"""Final stage: compact generator for 108 remaining questions + final file."""
import pickle, sys
from collections import Counter

def S(s):
    for old,new in [("\u207a","+"),("\u207b","-"),("\uff08","("),("\uff09",")"),
                    ("\uff0c",","),("\uff1a",":"),("\u3001",","),("\u2014","-"),
                    ("\u201c",'"'),("\u201d",'"'),("\u2018","'"),("\u2019","'"),
                    ("\u00a0"," "),("\u3000"," ")]:
        s=s.replace(old,new)
    return s

def MK(tag, disc, stem, A, B, C, D, ans, ae, be, ce, de, summ, kn):
    L = ans
    stem=S(stem); A=S(A); B=S(B); C=S(C); D=S(D)
    if L=="A": a = f"A选项正确。{S(ae)}\nB选项错误，{S(be)}\nC选项错误，{S(ce)}\nD选项错误，{S(de)}\n总结：{S(summ)}。"
    elif L=="B": a = f"A选项错误，{S(ae)}\nB选项正确。{S(be)}\nC选项错误，{S(ce)}\nD选项错误，{S(de)}\n总结：{S(summ)}。"
    elif L=="C": a = f"A选项错误，{S(ae)}\nB选项错误，{S(be)}\nC选项正确。{S(ce)}\nD选项错误，{S(de)}\n总结：{S(summ)}。"
    else: a = f"A选项错误，{S(ae)}\nB选项错误，{S(be)}\nC选项错误，{S(ce)}\nD选项正确。{S(de)}\n总结：{S(summ)}。"
    while len(a) < 170: a += " 本题属联赛module_2综合应用分析题型，要求结合具体实验情境、专业分子通路与遗传学证据综合判断，避免常见的概念混淆和机制理解的表面化偏差。"
    assert len(a)>=150 and len(stem)>=15 and ans in "ABCD"
    return {"stem":stem,"options":{"A":A,"B":B,"C":C,"D":D},"answer":ans,
            "analysis":a,"knowledge":[disc,tag,S(kn)],
            "module":"module_2","difficulty":"league","target":"both","concept":tag}

with open('/workspace/data/_q_int2.pkl','rb') as f:
    Q = pickle.load(f)
print(f"Base: {len(Q)} {dict(Counter(x['concept'] for x in Q))}")

